source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc) and dr != 0:
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                cells = [(r1 + k * sr, c1 + k * sc) for k in range(abs(dr) + 1)]
                segments.append((cells, sr == sc))
                for r, c in cells:
                    if out[r][c] == bg:
                        out[r][c] = 1
    for r, c in sixes:
        for cells, slope_down in segments:
            if (r, c) in cells:
                if slope_down:
                    for rr in range(h):
                        cc = r + c - rr
                        if 0 <= cc < w and out[rr][cc] == bg:
                            out[rr][cc] = 6
                else:
                    diff = r - c
                    for rr in range(h):
                        cc = rr - diff
                        if 0 <= cc < w and out[rr][cc] == bg:
                            out[rr][cc] = 6
    return out
